import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Güç Kurulumu","description":"","frontmatter":{},"headers":[],"relativePath":"tr/qgc-user-guide/setup_view/power.md","filePath":"tr/qgc-user-guide/setup_view/power.md"}`),a={name:`tr/qgc-user-guide/setup_view/power.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="guc-kurulumu" tabindex="-1">Güç Kurulumu <a class="header-anchor" href="#guc-kurulumu" aria-label="Permalink to “Güç Kurulumu”">​</a></h1><p>The <em>Power Setup</em> screen is used to configure battery parameters and calibrate ESCs.</p><h2 id="batarya-voltaj-akım-kalibrasyonu" tabindex="-1">Batarya Voltaj/Akım Kalibrasyonu <a class="header-anchor" href="#batarya-voltaj-akım-kalibrasyonu" aria-label="Permalink to “Batarya Voltaj/Akım Kalibrasyonu”">​</a></h2><p>Batarya/güç modülünüz için veri sayfasından verileri girin: hücre sayısı, hücre başına tam voltaj, hücre başına boş voltaj. Eğer varsa, voltaj bölücü ve volt başına amper bilgilerini de girin.</p><p><em>QGroundControl</em>, ölçümlerden uygun voltaj bölücü ve volt başına amper değerlerini hesaplamak için kullanılabilir:</p><ol><li>Bir multimetre kullanarak pilden gelen voltajı ölçün.</li><li><em>Voltage divider</em>&#39;ın yanındaki <strong>Calculate</strong> butonuna tıklayın. On the prompt that appears:</li><li>Ölçülen voltajı girin.</li><li><strong>Calculate</strong>&#39;e tıklayarak yeni bir voltaj bölücü değeri oluşturun.</li><li>Değeri ana forma kaydetmek için <strong>Close</strong>&#39;a tıklayın.</li><li>Bataryadaki akımı ölçün.</li><li><em>Amps per volt</em>&#39;un yanındaki <strong>Calculate</strong> butonuna tıklayın. On the prompt that appears:</li><li>Ölçülen akımı girin.</li><li><strong>Calculate</strong>&#39;e tıklayarak yeni bir <em>volt başına akım</em> değeri oluşturun.</li><li>Değeri ana forma kaydetmek için <strong>Close</strong>&#39;a tıklayın.</li></ol><h2 id="gelismis-guc-ayarları" tabindex="-1">Gelişmiş Güç Ayarları <a class="header-anchor" href="#gelismis-guc-ayarları" aria-label="Permalink to “Gelişmiş Güç Ayarları”">​</a></h2><p>Gelişmiş güç ayarlarını özelleştirmek için <strong>Show Advanced Settings</strong> onay kutusuna tıklayın.</p><h3 id="tam-yukte-voltaj-dususu" tabindex="-1">Tam Yükte Voltaj Düşüşü <a class="header-anchor" href="#tam-yukte-voltaj-dususu" aria-label="Permalink to “Tam Yükte Voltaj Düşüşü”">​</a></h3><p>Bataryalar yüksek motor yüklemelerinde daha az voltaj gösterir. Motorlar boştayken ve tam kapasitede çalışırkenki volt farkını batarya hücrelerinin sayısına bölerek girin. Emin değilseniz varsayılan değer kullanılmalıdır!</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Eğer değer çok yüksekse batarya deep-discharged olabilir ve hasar görebilir.</p></div><h2 id="esc-pwm-minimum-ve-maksimum-kalibrasyonu" tabindex="-1">ESC PWM Minimum ve Maksimum Kalibrasyonu <a class="header-anchor" href="#esc-pwm-minimum-ve-maksimum-kalibrasyonu" aria-label="Permalink to “ESC PWM Minimum ve Maksimum Kalibrasyonu”">​</a></h2><p>ESC&#39;nin max/min PWM değerlerini kalibre etmek için:</p><ol><li>Pervaneleri çıkarın.</li><li>Aracı QGC&#39;ye USB (sadece) aracılığı ile bağlayın.</li><li><strong>Calibrate</strong> butonuna basın.</li></ol><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Never attempt ESC calibration with props on.</p><p>ESC kalibrasyonu sırasında motorlar dönmemelidir. Bununla birlikte, bir ESC kalibrasyon sırasını doğru şekilde desteklemez/tespit etmezse, motoru maksimum hızda çalıştırarak PWM girişine yanıt verecektir.</p></div>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};